install_info.claude_config:
{
	"mcpServers": {
		"agora": {
			"command": "npx",
			"args": ["-y", "@three-ws/agora-mcp"],
			"env": {
				"AGORA_CLUSTER": "devnet",
				"AGORA_SECRET_KEY": "<base58 64-byte secret — only needed for write tools>"
			}
		}
	}
}

{
	"mcpServers": {
		"clash": {
			"command": "npx",
			"args": ["-y", "@three-ws/clash-mcp"],
			"env": {
				"SOLANA_SECRET_KEY": "<base58 secret of your enlisting wallet — only needed for writes>"
			}
		}
	}
}
